BEGIN;SET LOCAL statement_timeout='8s';SET LOCAL lock_timeout='1s';SELECT pg_advisory_xact_lock(2026083000261022);DO $patch$ DECLARE old text;updated text;r record;BEGIN IF EXISTS(SELECT 1 FROM cron.job WHERE jobid=596 AND active) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE status='LEASED') OR NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton AND owner_id='top3000-recovery-20261023-root-4b1314bcb5c2' AND owner_fence=2 AND stop_generation=0 AND enabled AND NOT stopped AND admitted_until>clock_timestamp()) THEN RAISE EXCEPTION 'PAUSED_CURRENT_ROOT_REQUIRED';END IF;SELECT * INTO r FROM net._http_response WHERE id=7088;IF r.status_code IS DISTINCT FROM 403 OR r.timed_out OR r.content::jsonb->>'provider_requested' IS DISTINCT FROM 'false' OR (SELECT provider_requests FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton)<>5924 THEN RAISE EXCEPTION 'D02_V2_AUTH_PROBE_FAILED';END IF;old:=pg_get_functiondef('population_top3000_202608_202609_v1.pipeline_dispatch_edge_v1(uuid,text,text)'::regprocedure);IF old IS DISTINCT FROM $original$CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.pipeline_dispatch_edge_v1(p_attempt uuid, p_token text, p_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
